#!/bin/bash\n\n# Script для сборки Android приложения\n# Использование: ./build.sh [debug|release]\n\nset -e\n\nBUILD_TYPE=\"${1:-debug}\"\nPROJECT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n\necho \"================================\"\necho \"MUST Inverter Monitor Builder\"\necho \"================================\"\necho \"\"\necho \"Build Type: $BUILD_TYPE\"\necho \"Project Dir: $PROJECT_DIR\"\necho \"\"\n\n# Проверка наличия gradlew\nif [ ! -f \"$PROJECT_DIR/gradlew\" ]; then\n    echo \"❌ gradlew not found. Please run this script from android directory.\"\n    exit 1\nfi\n\n# Сборка\necho \"🔨 Building $BUILD_TYPE APK...\"\n\ncase $BUILD_TYPE in\n    debug)\n        $PROJECT_DIR/gradlew -p $PROJECT_DIR assembleDebug\n        APK_PATH=\"$PROJECT_DIR/app/build/outputs/apk/debug/app-debug.apk\"\n        ;;\n    release)\n        if [ ! -f \"$PROJECT_DIR/keystore.properties\" ]; then\n            echo \"❌ keystore.properties not found for release build\"\n            echo \"Please create keystore first: keytool -genkey -v -keystore ...\"\n            exit 1\n        fi\n        $PROJECT_DIR/gradlew -p $PROJECT_DIR assembleRelease\n        APK_PATH=\"$PROJECT_DIR/app/build/outputs/apk/release/app-release.apk\"\n        ;;\n    *)\n        echo \"❌ Unknown build type: $BUILD_TYPE\"\n        echo \"Usage: $0 [debug|release]\"\n        exit 1\n        ;;\nesac\n\nif [ -f \"$APK_PATH\" ]; then\n    APK_SIZE=$(du -h \"$APK_PATH\" | cut -f1)\n    echo \"\"\n    echo \"✅ Build successful!\"\n    echo \"📦 APK: $APK_PATH\"\n    echo \"📊 Size: $APK_SIZE\"\n    echo \"\"\n    echo \"To install: adb install -r $APK_PATH\"\nelse\n    echo \"❌ Build failed: APK not found at $APK_PATH\"\n    exit 1\nfi\n"